/* ==================== لوحة التحكم ==================== */
function renderDashboard(){
  const active=activeEmps();const alerts=computeAlerts();
  const expired=alerts.filter(a=>a.kind==='doc'&&a.lvl===0).length,soon=alerts.filter(a=>a.kind==='doc'&&a.lvl===1).length,later=alerts.filter(a=>a.kind==='doc'&&a.lvl===2).length;
  const salDue=alerts.filter(a=>a.kind==='sal').length;const onLeave=active.filter(onLeaveToday).length;
  const mk=monthKey(today());const paidThis=S.payments.filter(p=>p.month===mk);
  const totalAED=active.reduce((s,e)=>s+toAED(net(e),e.currency),0);const paidAED=paidThis.reduce((s,p)=>s+toAED(+p.amount,p.currency),0);const pct=totalAED?Math.min(100,Math.round(paidAED/totalAED*100)):0;
  const eosTotal=active.reduce((s,e)=>{const g=eosCalc(e);return s+(g?toAED(g.gratuity,e.currency):0)},0);
  if(!S.employees.length)return `<div class="card" style="text-align:center;padding:60px 20px"><div style="font-size:3rem">👋</div><h2>أهلاً بك في منصة شؤون الموظفين</h2><p class="muted">ابدأ بإضافة أول موظف، أو استورد قائمة من Excel، أو حمّل بيانات تجريبية لتستكشف المنصة.</p><div class="toolbar" style="justify-content:center"><button class="btn primary" onclick="openEmpForm()">＋ إضافة موظف</button><button class="btn" onclick="openOfferForm()">📨 عرض عمل لمرشح</button><button class="btn" onclick="importCSVDialog()">📥 استيراد من Excel</button><button class="btn" onclick="loadDemo()">🧪 بيانات تجريبية</button><button class="btn" onclick="restoreBackup()">📂 استعادة نسخة</button></div></div>`;
  setTimeout(drawDashCharts,0);
  return `
  <div class="grid g4" style="margin-bottom:16px">
    <div class="tile ${expired?'danger':'ok'}" onclick="docFilter.view='expired';go('documents')"><div class="lbl">مستندات منتهية</div><div class="num">${expired}</div><div class="sub">تحتاج تجديد فوري</div></div>
    <div class="tile ${soon?'danger':'ok'}" onclick="docFilter.view='soon';go('documents')"><div class="lbl">تنتهي خلال ${Math.min(...S.settings.thresholds)} يوم</div><div class="num">${soon}</div><div class="sub">ابدأ إجراءات التجديد</div></div>
    <div class="tile ${later?'warn':'ok'}" onclick="docFilter.view='later';go('documents')"><div class="lbl">تنتهي خلال ${Math.max(...S.settings.thresholds)} يوم</div><div class="num">${later}</div><div class="sub">للمتابعة</div></div>
    <div class="tile ${salDue?'warn':'ok'}" onclick="go('payroll')"><div class="lbl">رواتب مستحقة الآن</div><div class="num">${salDue}</div><div class="sub">${paidThis.length} من ${active.length} صُرفت هذا الشهر</div></div>
  </div>
  <div class="grid g4" style="margin-bottom:16px">
    <div class="tile" onclick="go('employees')"><div class="lbl">الموظفون النشطون</div><div class="num">${active.length}</div><div class="sub">${S.employees.length-active.length} غير نشط · ${onLeave} في إجازة اليوم</div></div>
    <div class="tile"><div class="lbl">إجمالي الرواتب الشهرية</div><div class="num" style="font-size:1.4rem">${n0(totalAED)} د.إ</div><div class="sub">≈ ${n0(totalAED/S.settings.rate)} $</div></div>
    <div class="tile"><div class="lbl">صرف ${monthName(mk)}</div><div class="num" style="font-size:1.4rem">${pct}%</div><div class="prog"><i style="width:${pct}%"></i></div><div class="sub">${n0(paidAED)} من ${n0(totalAED)} د.إ</div></div>
    <div class="tile info" onclick="go('reports')"><div class="lbl">التزام نهاية الخدمة المتراكم</div><div class="num" style="font-size:1.4rem">${n0(eosTotal)} د.إ</div><div class="sub">لو أُنهيت كل العقود اليوم</div></div>
  </div>
  <div class="grid g4" style="margin-bottom:16px">${(()=>{const t=iso(today());const by=k=>active.filter(e=>(attOf(e,t)||{}).status===k).length;const bal=treasuryBalance();const pend=S.advances.filter(a=>a.status==='pending').length+S.expenses.filter(x=>x.status==='pending').length;const cust=S.advances.filter(a=>a.kind==='custody'&&a.status==='disbursed').reduce((s,a)=>s+toAED(advRemaining(a),a.currency),0);return `<div class="tile" onclick="go('field')"><div class="lbl">🚚 في الميدان الآن</div><div class="num">${by('field')+by('mission')}</div><div class="sub">${by('present')} بالمقر · ${by('absent')} غائب</div></div><div class="tile ${bal<0?'danger':'ok'}" onclick="go('finance')"><div class="lbl">🏦 رصيد الخزنة</div><div class="num" style="font-size:1.4rem">${n0(bal)} د.إ</div><div class="sub">عُهد مفتوحة ${n0(cust)}</div></div><div class="tile ${pend?'warn':'ok'}" onclick="finTab='advances';go('finance')"><div class="lbl">🔐 بانتظار قرار المدير</div><div class="num">${pend}</div><div class="sub">سلف وعُهد ومصروفات</div></div><div class="tile info" onclick="printDigest()"><div class="lbl">🖨️ تقرير المدير اليومي</div><div class="num" style="font-size:1.1rem;margin-top:8px">اطبع الآن</div><div class="sub">من في الميدان، الخزنة، الطلبات، التنبيهات</div></div>`})()}</div>
  <div class="grid g32">
    <div class="card"><div class="card-head" style="padding:0 0 12px;margin-bottom:6px"><h2>🔔 أهم التنبيهات</h2><button class="btn sm" onclick="go('alerts')">عرض الكل (${alerts.length})</button></div>
      ${alerts.length?alerts.slice(0,10).map(a=>`<div class="list-alert" ${a.page?`data-go-page="${a.page}"`:`data-go-emp="${a.emp.id}"`}><span><span class="dot" style="background:${a.lvl<=1?'var(--danger)':a.lvl===2?'var(--warn)':'var(--info)'}"></span>${esc(a.txt)}</span><span class="badge ${a.cls}">${kindLabel(a.kind)}</span></div>`).join(''):'<div class="empty">✅ لا توجد تنبيهات — كل شيء تحت السيطرة</div>'}
    </div>
    <div class="card"><h2>📊 تكلفة الرواتب — آخر 6 أشهر (د.إ)</h2><div class="chart-box"><canvas id="chCost"></canvas></div></div>
  </div>
  <div class="grid g3">
    <div class="card"><h2>📆 مستندات تنتهي خلال 12 شهر</h2><div class="chart-box"><canvas id="chExp"></canvas></div></div>
    <div class="card"><h2>🏢 الأقسام</h2><div class="chart-box"><canvas id="chDept"></canvas></div></div>
    <div class="card"><h2>📅 الرواتب القادمة</h2>${renderUpcomingSalaries()}</div>
  </div>`;
}
const kindLabel=k=>({tax:'ضرائب',offer:'عرض عمل',cdoc:'مستند منشأة',doc:'مستند',sal:'راتب',leave:'إجازة',anniv:'ذكرى تعيين',contract:'عقد',bday:'مناسبة',cash:'الخزنة',adv:'سلف وعُهد',exp:'مصروفات',att:'حضور'}[k]||k);
function monthsBack(n){const out=[];for(let i=n-1;i>=0;i--){const d=new Date(today().getFullYear(),today().getMonth()-i,1);out.push(monthKey(d));}return out;}
function drawDashCharts(){const ms=monthsBack(6);mkChart('chCost',{type:'bar',data:{labels:ms.map(k=>monthName(k).replace(/\s\d{4}/,'')),datasets:[{label:'مصروف',data:ms.map(k=>S.payments.filter(p=>p.month===k).reduce((s,p)=>s+toAED(+p.amount,p.currency),0)),backgroundColor:'#12B5A6',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{callback:v=>n0(v)}}}}});
  const fut=[];for(let i=0;i<12;i++){const d=new Date(today().getFullYear(),today().getMonth()+i,1);fut.push(monthKey(d));}
  mkChart('chExp',{type:'bar',data:{labels:fut.map(k=>monthName(k).replace(/\s\d{4}/,'')),datasets:[{label:'مستندات',data:fut.map(k=>S.documents.filter(d=>{const e=empById(d.emp_id);return e&&e.status!=='inactive'&&d.expiry_date&&d.expiry_date.startsWith(k)}).length),backgroundColor:fut.map((k,i)=>i<3?'#E25555':i<6?'#F2A93C':'#12B5A6'),borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{stepSize:1}}}}});
  const m={};activeEmps().forEach(e=>{const d=e.dept||'بدون قسم';m[d]=(m[d]||0)+1});const arr=Object.entries(m).sort((a,b)=>b[1]-a[1]);
  mkChart('chDept',{type:'doughnut',data:{labels:arr.map(a=>a[0]),datasets:[{data:arr.map(a=>a[1]),backgroundColor:CHART_COLORS,borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'62%',plugins:{legend:{position:'left',labels:{boxWidth:12}}}}});}
function renderUpcomingSalaries(){const list=activeEmps().map(e=>({e,s:salaryDue(e)})).filter(x=>x.s.state!=='paid'&&x.s.state!=='na').sort((a,b)=>(a.s.due||0)-(b.s.due||0)).slice(0,7);if(!list.length)return '<div class="empty">تم صرف جميع رواتب هذا الشهر 🎉</div>';return list.map(({e,s})=>`<div class="list-alert" data-go-emp="${e.id}"><span><b>${esc(e.name)}</b><div class="mini muted">${money(net(e),e.currency)}</div></span><span class="badge ${s.state==='late'?'b-danger':s.state==='due'?'b-warn':'b-muted'}">${s.state==='late'?`متأخر ${s.days} يوم`:s.days===0?'اليوم':`بعد ${s.days} يوم`}</span></div>`).join('');}

/* ==================== مركز التنبيهات ==================== */
let alertFilter='all';
function renderAlerts(){const all=computeAlerts();const list=alertFilter==='all'?all:alertFilter==='urgent'?all.filter(a=>a.lvl<=1):all.filter(a=>a.kind===alertFilter);const counts=k=>all.filter(a=>k==='all'||(k==='urgent'?a.lvl<=1:a.kind===k)).length;
  const chips=[['all','الكل'],['urgent','عاجل'],['doc','مستندات'],['cdoc','مستندات المنشأة'],['sal','رواتب'],['adv','سلف وعُهد'],['exp','مصروفات'],['cash','الخزنة'],['contract','عقود'],['leave','إجازات'],['att','حضور']];
  return `<div class="card tight"><div class="card-head"><div class="toolbar">${chips.map(([k,l])=>`<span class="chip ${alertFilter===k?'on':''}" onclick="alertFilter='${k}';render()">${l} <b>${counts(k)}</b></span>`).join('')}</div><div class="toolbar"><button class="btn" onclick="exportCSV('alerts')">⬇️ تصدير</button><button class="btn" onclick="printAlerts()">🖨️ طباعة</button></div></div>
  ${list.length?`<table><thead><tr><th>الأولوية</th><th>النوع</th><th>التفاصيل</th><th>الموظف</th><th></th></tr></thead><tbody>${list.map(a=>`<tr><td><span class="dot" style="background:${a.lvl<=1?'var(--danger)':a.lvl===2?'var(--warn)':'var(--info)'}"></span>${a.lvl<=1?'عاجل':a.lvl===2?'متابعة':'معلومة'}</td><td><span class="badge ${a.cls}">${kindLabel(a.kind)}</span></td><td>${esc(a.txt)}</td><td><b ${a.emp.id?`data-go-emp="${a.emp.id}"`:''} style="cursor:pointer">${esc(a.emp.name)}</b></td><td>${a.kind==='doc'||(a.kind==='cdoc'&&a.doc)?`<button class="btn sm" onclick="renewDoc('${a.doc.id}')">🔄 تجديد</button>`:a.kind==='sal'?`<button class="btn sm ok" onclick="markPaid('${a.emp.id}','${monthKey(today())}')">✅ صرف</button>`:a.page?`<button class="btn sm" data-go-page="${a.page}">فتح</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">✅ لا توجد تنبيهات في هذا التصنيف</div>'}</div>`;}
function printAlerts(){const a=computeAlerts();api.printHTML(letterShell(`<h2>تقرير التنبيهات — ${fmtDate(iso(today()))}</h2><table border="1" cellpadding="6" style="border-collapse:collapse;width:100%"><tr><th>#</th><th>النوع</th><th>التفاصيل</th></tr>${a.map((x,i)=>`<tr><td>${i+1}</td><td>${kindLabel(x.kind)}</td><td>${esc(x.txt)}</td></tr>`).join('')}</table>`));}

/* ==================== الموظفون ==================== */
let empFilter={q:'',dept:'',status:'active',sort:'name'};
function filteredEmps(){let list=S.employees.filter(e=>e.status!=='probation'&&(empFilter.status==='all'||(empFilter.status==='active'?e.status!=='inactive':e.status==='inactive'))&&(!empFilter.dept||e.dept===empFilter.dept)&&(!empFilter.q||[e.name,e.name_en,e.code,e.job,e.nationality,e.phone,e.dept].join(' ').toLowerCase().includes(empFilter.q.toLowerCase())));
  const k=empFilter.sort;list.sort((a,b)=>k==='name'?(a.name||'').localeCompare(b.name||'','ar'):k==='salary'?toAED(net(b),b.currency)-toAED(net(a),a.currency):k==='hire'?(a.hire_date||'').localeCompare(b.hire_date||''):(a.dept||'').localeCompare(b.dept||'','ar'));return list;}
function renderEmployees(){if(empMainTab==='jobs')return renderJobsPage();if(empMainTab==='prob')return renderProbation();const list=filteredEmps();const depts=[...new Set([...S.settings.departments,...S.employees.map(e=>e.dept).filter(Boolean)])];
  return empMainTabs()+`<div class="card tight"><div class="card-head"><div class="toolbar">
    <input class="search" placeholder="🔍 بحث بالاسم أو الرقم أو الوظيفة…" value="${esc(empFilter.q)}" oninput="empFilter.q=this.value;refreshEmpTable()">
    <select class="search" style="min-width:140px" onchange="empFilter.dept=this.value;render()"><option value="">كل الأقسام</option>${depts.map(d=>`<option ${empFilter.dept===d?'selected':''}>${esc(d)}</option>`).join('')}</select>
    <select class="search" style="min-width:120px" onchange="empFilter.status=this.value;render()"><option value="active" ${empFilter.status==='active'?'selected':''}>النشطون</option><option value="inactive" ${empFilter.status==='inactive'?'selected':''}>غير النشطين</option><option value="all" ${empFilter.status==='all'?'selected':''}>الكل</option></select>
    <select class="search" style="min-width:120px" onchange="empFilter.sort=this.value;render()"><option value="name">ترتيب: الاسم</option><option value="salary" ${empFilter.sort==='salary'?'selected':''}>الراتب</option><option value="hire" ${empFilter.sort==='hire'?'selected':''}>تاريخ التعيين</option><option value="dept" ${empFilter.sort==='dept'?'selected':''}>القسم</option></select>
    </div><div class="toolbar"><span class="muted mini">${list.length} موظف</span><button class="btn" onclick="importCSVDialog()">📥 استيراد</button><button class="btn" onclick="printAllStatements()">🖨️ كشف الجميع</button><button class="btn" onclick="exportCSV('employees')">⬇️ تصدير Excel</button><button class="btn primary" onclick="openEmpForm()">＋ موظف جديد</button></div></div>
    <div class="table-wrap" id="empTable">${empTableHTML(list)}</div></div>`;}
function refreshEmpTable(){const el=$('#empTable');if(!el)return;el.innerHTML=empTableHTML(filteredEmps());el.querySelectorAll('[data-go-emp]').forEach(x=>x.onclick=()=>go('employee',x.dataset.goEmp));}
function empTableHTML(list){if(!list.length)return '<div class="empty">لا يوجد موظفون مطابقون</div>';
  return `<table><thead><tr><th>#</th><th>الاسم</th><th>الوظيفة / القسم</th><th>الجنسية</th><th>المستندات</th><th>الراتب</th><th>راتب الشهر</th><th>الإجازة</th><th></th></tr></thead><tbody>${list.map(e=>{const docs=S.documents.filter(d=>d.emp_id===e.id);const worst=docs.length?Math.min(...docs.map(d=>docStatus(d).lvl)):9;const badge=worst===0?'<span class="badge b-danger">منتهي</span>':worst===1?'<span class="badge b-danger">ينتهي قريباً</span>':worst===2?'<span class="badge b-warn">للمتابعة</span>':worst===3?'<span class="badge b-ok">سارية</span>':'<span class="badge b-muted">لا مستندات</span>';const s=salaryDue(e);const sb=s.state==='paid'?'<span class="badge b-ok">تم الصرف</span>':s.state==='late'?'<span class="badge b-danger">متأخر</span>':s.state==='due'?'<span class="badge b-warn">مستحق</span>':s.state==='na'?'<span class="badge b-muted">—</span>':`<span class="badge b-muted">يوم ${e.pay_day||25}</span>`;const lv=onLeaveToday(e);const lb=leaveBalance(e);
  return `<tr class="clickable" data-go-emp="${e.id}"><td class="muted mini">${esc(e.code||'')}</td><td><div style="display:flex;align-items:center;gap:9px"><span class="ccav" style="width:32px;height:32px${e.photo?';background:none':''}">${e.photo?`<img src="${esc(e.photo)}" alt="">`:esc(initials(e.name))}</span><div><b>${esc(e.name)}</b>${e.status==='inactive'?' <span class="badge b-muted">غير نشط</span>':''}${lv?' <span class="badge b-info">في إجازة</span>':''}<div class="muted mini" dir="ltr" style="text-align:right">${esc(e.phone||'')}</div></div></div></td><td>${esc(e.job||'')}<div class="muted mini">${esc(e.dept||'')}</div></td><td>${esc(e.nationality||'')}</td><td>${badge} <span class="muted mini">${docs.length}</span></td><td class="num">${money(netAfter(e),e.currency)}${instNote(e)}</td><td>${sb}</td><td class="num">${lb.balance} يوم</td><td><button class="btn sm" onclick="event.stopPropagation();openEmpForm('${e.id}')">تعديل</button></td></tr>`}).join('')}</tbody></table>`;}

function renderProbation(){const list=probationEmps().sort((a,b)=>(a.name||'').localeCompare(b.name||'','ar'));
  return empMainTabs()+`<div class="card tight"><div class="card-head"><div><h2 style="margin:0">🧪 الموظفون تحت التجربة</h2><div class="muted mini">موظفون قيد التجربة — لهم ملف كامل مثل أي موظف (راتب، سلف، إجازات، مستندات). الفرق الوحيد أنهم مُعلَّمون «تحت التجربة» وفي قائمة منفصلة، حتى تضغط «✅ تعيين» فيُنقلون لقسم الموظفين المثبّتين.</div></div><button class="btn primary" onclick="openEmpForm(null,true)">＋ إضافة تحت التجربة</button></div>
  <div class="table-wrap">${list.length?`<table><thead><tr><th>#</th><th>الاسم</th><th>الوظيفة / القسم</th><th>الجنسية</th><th>تاريخ البدء</th><th>الراتب</th><th></th></tr></thead><tbody>${list.map(e=>`<tr class="clickable" data-go-emp="${e.id}"><td class="muted mini">${esc(e.code||'')}</td><td><b>${esc(e.name)}</b> <span class="badge b-warn">تحت التجربة</span><div class="muted mini" dir="ltr" style="text-align:right">${esc(e.phone||'')}</div></td><td>${esc(e.job||'')}<div class="muted mini">${esc(e.dept||'')}</div></td><td>${esc(e.nationality||'')}</td><td>${fmtDate(e.hire_date)}</td><td class="num">${money(net(e),e.currency)}</td><td><button class="btn sm ok" onclick="event.stopPropagation();hireProbation('${e.id}')">✅ تعيين</button> <button class="btn sm" onclick="event.stopPropagation();openEmpForm('${e.id}')">تعديل</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">لا يوجد موظفون تحت التجربة. اضغط «＋ إضافة تحت التجربة» لإضافة مرشّح جديد.</div>'}</div></div>`;}
async function hireProbation(id){const e=empById(id);if(!e||e.status!=='probation')return;if(!await confirmBox(`تعيين ${e.name} رسمياً ونقله إلى قسم الموظفين المثبّتين في الشركة؟`,'نعم، عيّنه'))return;await DB.upsert('employees',{...e,status:'active',hire_date:e.hire_date||iso(today())});await DB.upsert('notes',{id:uid(),emp_id:id,date:iso(today()),kind:'ملاحظة',text:'تم تعيينه رسمياً ونقله من تحت التجربة إلى موظفي الشركة'});toast('تم التعيين ✅ — الموظف الآن ضمن موظفي الشركة','ok');go('employees');}
function openEmpForm(id,asProbation){const e=id?empById(id):{status:asProbation?'probation':'active',currency:'AED',pay_day:25,hire_date:iso(today()),annual_leave:S.settings.annualLeave};const depts=[...new Set([...S.settings.departments,...S.employees.map(x=>x.dept).filter(Boolean)])];
  openModal(id?'تعديل بيانات الموظف':(asProbation?'إضافة موظف تحت التجربة':'إضافة موظف جديد'),`
  <div style="display:flex;align-items:center;gap:14px;margin-bottom:10px"><div id="f_photoPrev" class="avatar" style="width:76px;height:76px;overflow:hidden;${e.photo?'background:none':''}">${e.photo?`<img src="${esc(e.photo)}" alt="" style="width:100%;height:100%;object-fit:cover">`:'👤'}</div><div><input type="hidden" id="f_photo" value="${esc(e.photo||'')}"><input type="file" id="f_photoFile" accept="image/*" style="display:none" onchange="empPhotoPick(this)"><button type="button" class="btn sm" onclick="document.getElementById('f_photoFile').click()">📷 رفع صورة الموظف</button> <button type="button" class="btn sm" onclick="empPhotoClear()">إزالة الصورة</button><div class="muted mini">صورة واضحة للوجه لسهولة التعرّف على الموظف</div></div></div>
  <div class="frow3"><div class="field"><label>الاسم الكامل (عربي) *</label><input id="f_name" value="${esc(e.name||'')}"></div><div class="field"><label>الاسم بالإنجليزية (للخطابات)</label><input id="f_name_en" value="${esc(e.name_en||'')}" dir="ltr"></div><div class="field"><label>الرقم الوظيفي</label><input id="f_code" value="${esc(e.code||'')}" placeholder="EMP-001"></div></div>
  <div class="frow3"><div class="field"><label>الوظيفة</label><input id="f_job" value="${esc(e.job||'')}"></div><div class="field"><label>القسم</label><input id="f_dept" list="deptList" value="${esc(e.dept||'')}"><datalist id="deptList">${depts.map(d=>`<option value="${esc(d)}">`).join('')}</datalist></div><div class="field"><label>الجنسية</label><input id="f_nat" value="${esc(e.nationality||'')}"></div></div>
  <div class="frow3"><div class="field"><label>رقم جواز السفر</label><input id="f_passport" value="${esc(e.passport_no||'')}" dir="ltr" autocomplete="off"></div><div class="field"><label>مكان العمل داخل الشركة</label><input id="f_workloc" value="${esc(e.work_location||'')}" placeholder="مثال: المخزن الرئيسي / موقع برج النخيل"></div>${projField('f_proj',e.project_id||'','المشروع الحالي')}</div>
  <div class="frow4"><div class="field"><label>الفئة</label><select id="f_cat"><option value="إداري" ${e.category!=='ميداني'?'selected':''}>إداري / مكتبي</option><option value="ميداني" ${e.category==='ميداني'?'selected':''}>ميداني (عامل / فني / مندوب)</option></select></div><div class="field"><label>التخصص (اختياري)</label><select id="f_trade" onchange="if(this.value==='__new__')addNewTrade(this)"><option value="">— بدون تخصص —</option>${[...new Set([...(S.settings.trades&&S.settings.trades.length?S.settings.trades:DEFAULT_SETTINGS.trades),...(e.trade?[e.trade]:[])])].map(t=>`<option ${e.trade===t?'selected':''}>${esc(t)}</option>`).join('')}<option value="__new__">➕ إضافة تخصص جديد…</option></select></div><div class="field"><label>المستوى</label><select id="f_level"><option value="">—</option>${['مبتدئ','فني','فني أول','مشرف'].map(l=>`<option ${e.level===l?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>لديه سيارة / رخصة</label><select id="f_vehicle"><option value="0">لا</option><option value="1" ${+e.vehicle?'selected':''}>نعم</option></select></div></div>
  <div class="frow4"><div class="field"><label>الهاتف</label><input id="f_phone" value="${esc(e.phone||'')}" dir="ltr"></div><div class="field"><label>البريد</label><input id="f_email" value="${esc(e.email||'')}" dir="ltr"></div><div class="field"><label>تاريخ الميلاد</label><input type="date" id="f_birth" value="${esc(e.birth_date||'')}"></div><div class="field"><label>النوع</label><select id="f_gender"><option value="">—</option><option value="ذكر" ${e.gender==='ذكر'?'selected':''}>ذكر</option><option value="أنثى" ${e.gender==='أنثى'?'selected':''}>أنثى</option></select></div></div>
  <div class="frow3"><div class="field"><label>تاريخ التعيين *</label><input type="date" id="f_hire" value="${esc(e.hire_date||'')}"></div><div class="field"><label>تاريخ انتهاء العقد (اختياري)</label><input type="date" id="f_end" value="${esc(e.end_date||'')}"></div><div class="field"><label>الحالة</label><select id="f_status"><option value="active" ${e.status==='active'?'selected':''}>نشط (مثبّت)</option><option value="probation" ${e.status==='probation'?'selected':''}>تحت التجربة</option><option value="inactive" ${e.status==='inactive'?'selected':''}>غير نشط / منتهي</option></select></div></div>
  <h3 style="margin-top:6px">💵 الراتب</h3>
  <div class="frow4"><div class="field"><label>العملة</label><select id="f_cur"><option value="AED" ${e.currency==='AED'?'selected':''}>درهم (AED)</option><option value="USD" ${e.currency==='USD'?'selected':''}>دولار (USD)</option></select></div><div class="field"><label>الأساسي</label><input type="number" step="0.01" id="f_basic" value="${e.basic||''}" dir="ltr"></div><div class="field"><label>البدلات</label><input type="number" step="0.01" id="f_allow" value="${e.allowances||''}" dir="ltr"></div><div class="field"><label>خصومات ثابتة</label><input type="number" step="0.01" id="f_ded" value="${e.deductions||''}" dir="ltr"></div></div>
  <div class="frow"><div class="field"><label>هاتف الطوارئ</label><input id="f_emg" value="${esc(e.emergency_phone||'')}" dir="ltr"></div><div class="field"><label>رقم بطاقة العمل</label><input id="f_labour" value="${esc(e.labour_card||'')}" dir="ltr"></div></div>
  <div class="frow4"><div class="field"><label>يوم القبض</label><input type="number" min="1" max="31" id="f_payday" value="${e.pay_day||25}" dir="ltr"></div><div class="field"><label>رصيد الإجازة السنوي (يوم)</label><input type="number" id="f_leave" value="${e.annual_leave||30}" dir="ltr"></div><div class="field"><label>البنك</label><input id="f_bank" value="${esc(e.bank||'')}"></div><div class="field"><label>IBAN</label><input id="f_iban" value="${esc(e.iban||'')}" dir="ltr"></div></div>
  <div class="field"><label>ملاحظات</label><textarea id="f_notes" rows="2">${esc(e.notes||'')}</textarea></div>`,
  `<button class="btn primary" onclick="saveEmp('${id||''}')">حفظ</button><button class="btn" onclick="closeModal()">إلغاء</button>${id?`<button class="btn danger right" onclick="deleteEmp('${id}')">🗑️ حذف الموظف</button>`:''}`,true);
  setTimeout(()=>$('#f_name').focus(),50);}
async function addNewTrade(sel){const prev=sel.dataset.prev||'';const n=await miniPrompt('إضافة تخصص جديد','اكتب اسم التخصص (مثلاً: محاسب، سكرتير، كهربائي)');if(!n||!n.trim()){sel.value=prev;return}const t=n.trim();const exists=[...sel.options].find(o=>o.value===t&&o.value!=='__new__');if(!exists){const opt=document.createElement('option');opt.value=t;opt.textContent=t;sel.insertBefore(opt,sel.options[sel.options.length-1]);}sel.value=t;try{const cur=S.settings.trades||[];if(!cur.includes(t))await DB.setSetting('trades',[...cur,t]);toast('تمت إضافة التخصص ✅','ok');}catch(e){toast('تعذّر حفظ التخصص','err');}}
async function saveEmp(id){const name=fv('f_name');const trF=$('#f_trade');if(trF&&trF.value==='__new__')trF.value='';if(!name){toast('اسم الموظف مطلوب','err');if(window.shakeField)shakeField('f_name');return}if(!fv('f_hire')){toast('تاريخ التعيين مطلوب','err');if(window.shakeField)shakeField('f_hire');return}const code=fv('f_code');if(code&&S.employees.some(x=>x.code===code&&x.id!==id)){toast('الرقم الوظيفي مستخدم لموظف آخر','err');return}if(fv('f_end')&&fv('f_end')<fv('f_hire')){toast('تاريخ انتهاء العقد قبل تاريخ التعيين','err');return}
  const data={id:id||uid(),name,name_en:fv('f_name_en'),code:fv('f_code'),job:fv('f_job'),dept:fv('f_dept'),nationality:fv('f_nat'),passport_no:fv('f_passport'),work_location:fv('f_workloc'),...(document.getElementById('f_proj')?{project_id:fv('f_proj')||null}:{}),photo:fv('f_photo'),phone:fv('f_phone'),email:fv('f_email'),birth_date:fv('f_birth'),gender:fv('f_gender'),hire_date:fv('f_hire'),end_date:fv('f_end'),status:fv('f_status'),currency:fv('f_cur'),basic:fn('f_basic'),allowances:fn('f_allow'),deductions:fn('f_ded'),pay_day:Math.min(31,Math.max(1,fn('f_payday')||25)),annual_leave:fn('f_leave')||30,bank:fv('f_bank'),iban:fv('f_iban'),notes:fv('f_notes'),category:fv('f_cat'),trade:fv('f_trade'),level:fv('f_level'),vehicle:+fv('f_vehicle')||0,emergency_phone:fv('f_emg'),labour_card:fv('f_labour')};
  if(data.trade&&!S.settings.trades.includes(data.trade))await DB.setSetting('trades',[...S.settings.trades,data.trade]);
  if(data.dept&&!S.settings.departments.includes(data.dept))await DB.setSetting('departments',[...S.settings.departments,data.dept]);
  await DB.upsert('employees',data);closeModal();toast(id?'تم تحديث بيانات الموظف':'تمت إضافة الموظف','ok');if(current.page==='employee')render();else go('employee',data.id);}
async function deleteEmp(id){const e=empById(id);closeModal();if(!await confirmDel(`حذف الموظف "${e.name}" وكل مستنداته وسجل رواتبه وإجازاته نهائياً؟ (يُنصح بتغيير حالته إلى "غير نشط" بدلاً من الحذف)`,'حذف نهائي'))return;await DB.remove('employees',id);toast('تم حذف الموظف');go('employees');}

/* ==================== ملف الموظف ==================== */
let empTab='docs';
function renderEmployee(id){const e=empById(id);if(!e)return '<div class="card empty">الموظف غير موجود</div>';
  const docs=S.documents.filter(d=>d.emp_id===id).sort((a,b)=>docStatus(a).lvl-docStatus(b).lvl);const pays=S.payments.filter(p=>p.emp_id===id).sort((a,b)=>b.month.localeCompare(a.month));const leaves=S.leaves.filter(l=>l.emp_id===id).sort((a,b)=>b.start_date.localeCompare(a.start_date));const notes=S.notes.filter(n=>n.emp_id===id).sort((a,b)=>b.date.localeCompare(a.date));
  const s=salaryDue(e);const years=e.hire_date?daysBetween(e.hire_date,iso(today()))/365:0;const lb=leaveBalance(e);const eos=eosCalc(e);const lv=onLeaveToday(e);
  const advs=S.advances.filter(a=>a.emp_id===id).sort((a,b)=>(b.request_date||'').localeCompare(a.request_date||''));const exps=S.expenses.filter(x=>x.emp_id===id).sort((a,b)=>b.date.localeCompare(a.date));const sc=scorecard(e);
  const tabs=[['docs',`📄 المستندات (${docs.length})`],['pay',`💵 الرواتب (${pays.length})`],['fin',`💰 السلف (${advs.length})`],['att',`🚚 الحضور والأداء`],['leaves',`🏖️ الإجازات (${leaves.length})`],['eos','🧮 نهاية الخدمة'],['letters','✉️ الخطابات'],['assets',`🧰 عهدة المعدات (${S.assets.filter(a=>a.emp_id===id&&a.status!=='returned').length})`],['prom',`⬆️ الترقيات (${S.promotions.filter(x=>x.emp_id===id).length})`],['timeline',`📝 السجل (${notes.length})`],...(isAdminUI()?[['account',accountTabLabel(e)]]:[])];
  return `<button class="btn sm" onclick="go('employees')" style="margin-bottom:12px">← كل الموظفين</button>
  <div class="card"><div class="emp-head"><div class="avatar" style="${e.photo?'background:none;overflow:hidden;':''}">${e.photo?`<img src="${esc(e.photo)}" alt="" style="width:100%;height:100%;object-fit:cover">`:esc(initials(e.name))}</div><div><h2 style="margin:0">${esc(e.name)} ${e.status==='inactive'?'<span class="badge b-muted">غير نشط</span>':e.status==='probation'?'<span class="badge b-warn">تحت التجربة</span>':'<span class="badge b-ok">نشط</span>'} ${lv?`<span class="badge b-info">في إجازة ${esc(lv.type)} حتى ${fmtDate(lv.end_date)}</span>`:''}</h2><div class="muted">${esc(e.job||'—')} · ${esc(e.dept||'—')} · ${esc(e.code||'')} ${e.name_en?'· <span dir="ltr">'+esc(e.name_en)+'</span>':''}</div></div>
    <div class="toolbar right">${e.status==='probation'?`<button class="btn ok" onclick="hireProbation('${e.id}')">✅ تعيين في الشركة</button>`:''}<button class="btn" onclick="go('me','${e.id}')">🙋 بياناتي (كما يراها الموظف)</button><button class="btn" onclick="printPayslip('${e.id}')">🧾 كشف راتب</button>${e.status!=='inactive'?`<button class="btn" onclick="checkoutMenu('${e.id}')">🚪 تسجيل خروج</button>`:''}<button class="btn" onclick="empTab='letters';render()">✉️ خطاب</button><button class="btn" onclick="openPromote('${e.id}')">⬆️ ترقية</button><button class="btn" onclick="printEmpCard('${e.id}')">🪪 كارت الموظف</button><button class="btn" onclick="openEmpForm('${e.id}')">✏️ تعديل</button></div></div>
    <div class="kv" style="margin-top:16px">
      <div><small>الجنسية</small>${esc(e.nationality||'—')}</div><div><small>مكان العمل داخل الشركة</small>${esc(e.work_location||'—')}</div><div><small>رقم جواز السفر</small><span dir="ltr">${esc(e.passport_no||'—')}</span></div><div><small>الهاتف</small><span dir="ltr">${esc(e.phone||'—')}</span></div><div><small>تاريخ التعيين</small>${fmtDate(e.hire_date)} <span class="muted mini">(${years.toFixed(1)} سنة)</span></div>
      <div><small>الراتب الصافي${instSum(e)>0?' بعد خصم القسط':''}</small><b>${money(netAfter(e),e.currency)}</b> <span class="muted mini">≈ ${e.currency==='USD'?n0(toAED(netAfter(e),'USD'))+' د.إ':n0(toUSD(netAfter(e),'AED'))+' $'}</span>${instNote(e)}</div>
      <div><small>راتب ${monthName(monthKey(today()))}</small>${s.state==='paid'?'<span class="badge b-ok">تم الصرف '+fmtDate(s.p.paid_at)+'</span>':s.state==='late'?`<span class="badge b-danger">متأخر ${s.days} يوم</span>`:s.state==='due'?'<span class="badge b-warn">مستحق</span>':s.state==='na'?'<span class="badge b-muted">غير مستحق</span>':`<span class="badge b-muted">يوم ${e.pay_day} (بعد ${s.days} يوم)</span>`}</div>
      <div><small>رصيد الإجازة السنوية</small><b>${lb.balance}</b> يوم <span class="muted mini">من ${lb.accrued} مستحق</span></div>
      <div><small>مكافأة نهاية الخدمة (تقديري)</small><b>${eos&&eos.eligible?money(eos.gratuity,e.currency):'غير مستحقة بعد'}</b></div>
      <div><small>البنك / IBAN</small>${esc(e.bank||'—')} <span dir="ltr" class="mini">${esc(e.iban||'')}</span></div>
      ${e.end_date?`<div><small>انتهاء العقد</small>${fmtDate(e.end_date)} <span class="badge ${daysUntil(e.end_date)<=30?'b-danger':'b-muted'}">${daysUntil(e.end_date)} يوم</span></div>`:''}
    </div>${e.notes?`<p class="muted" style="margin:14px 0 0">📝 ${esc(e.notes)}</p>`:''}</div>
  <div class="card"><div class="tabs">${tabs.map(([k,l])=>`<button class="tab ${empTab===k?'active':''}" onclick="empTab='${k}';render()">${l}</button>`).join('')}</div>
    ${empTab==='docs'?`<div class="toolbar" style="margin-bottom:12px"><button class="btn primary" onclick="openDocForm('${e.id}')">＋ إضافة مستند</button></div>${docs.length?`<div class="table-wrap"><table><thead><tr><th>النوع</th><th>الرقم</th><th>الإصدار</th><th>الانتهاء</th><th>الحالة</th><th>الملف</th><th></th></tr></thead><tbody>${docs.map(d=>docRow(d,false)).join('')}</tbody></table></div>`:'<div class="empty">لا توجد مستندات. أضف الإقامة وجواز السفر لتفعيل التنبيهات.</div>'}`:''}
    ${empTab==='pay'?`<div class="toolbar" style="margin-bottom:12px">${s.state!=='paid'&&s.state!=='na'?`<button class="btn ok" onclick="markPaid('${e.id}','${monthKey(today())}')">✅ صرف راتب ${monthName(monthKey(today()))}</button>`:''}<button class="btn" onclick="openPayForm('${e.id}')">＋ تسجيل دفعة لشهر آخر</button></div>${pays.length?`<div class="table-wrap"><table><thead><tr><th>الشهر</th><th class="num">الأساسي</th><th class="num">البدلات</th><th class="num">مكافأة</th><th class="num">خصومات</th><th class="num">الصافي</th><th>تاريخ الصرف</th><th>ملاحظة</th><th></th></tr></thead><tbody>${pays.map(p=>`<tr><td>${monthName(p.month)}</td><td class="num">${n2(p.basic)}</td><td class="num">${n2(p.allowances)}</td><td class="num">${n2(p.bonus)}</td><td class="num">${n2(p.deductions)}</td><td class="num"><b>${money(p.amount,p.currency)}</b></td><td>${fmtDate(p.paid_at)}</td><td class="muted mini">${esc(p.note||'')}</td><td><button class="btn sm" onclick="printPayslip('${e.id}','${p.id}')">🧾</button> <button class="btn sm danger" onclick="deletePay('${p.id}')">حذف</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">لا توجد دفعات مسجلة</div>'}`:''}
    ${empTab==='fin'?`${(()=>{const p=empPosition(e);return `<div class="kv" style="margin-bottom:12px"><div><small>سلف متبقية عليه (دَين)</small><b>${n2(p.loanDue)}</b></div><div><small>🧰 عهدة مع الموظف (ليست دَيناً)</small><b>${n2(p.custDue)}</b></div><div><small>مصروفات دفعها له</small><b>${n2(p.reimbDue)}</b></div><div><small>رواتب متأخرة له</small><b>${n2(p.salaryDue)}</b></div><div style="background:${p.net>0.005?'var(--ok-2)':p.net<-0.005?'var(--danger-2)':'var(--sunken)'}"><small>صافي الموقف</small><b>${p.net>0.005?'له ':p.net<-0.005?'عليه ':''}${n2(Math.abs(p.net))}</b></div></div>`})()}<div class="toolbar" style="margin-bottom:12px"><button class="btn primary" onclick="openAdvanceForm('${e.id}')">＋ طلب سلفة</button><button class="btn primary" onclick="openCustodyChoice('${e.id}')">＋ عهدة</button><button class="btn" onclick="openExpenseForm('${e.id}')">＋ مصروف</button><button class="btn" onclick="openStatement('${e.id}')">📄 كشف حساب</button><span class="right muted mini">سلف قائمة: <b>${n2(advs.filter(a=>a.kind==='loan'&&a.status==='disbursed').reduce((s,a)=>s+advRemaining(a),0))}</b> · عُهد مفتوحة: <b>${n2(advs.filter(a=>a.kind==='custody'&&a.status==='disbursed').reduce((s,a)=>s+advRemaining(a),0))}</b></span></div>${advs.length?`<div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>النوع</th><th class="num">المبلغ</th><th>السبب</th><th>السداد</th><th class="num">المتبقي</th><th>الحالة</th><th>سند</th><th></th></tr></thead><tbody>${advs.map(a=>advRow(a,true)).join('')}</tbody></table></div>`:'<div class="empty">لا توجد سلف أو عُهد</div>'}${exps.length?`<h3 style="margin-top:16px">🧾 مصروفات صرفها</h3><table><thead><tr><th>التاريخ</th><th>التصنيف</th><th>البيان</th><th class="num">المبلغ</th><th>الحالة</th></tr></thead><tbody>${exps.slice(0,20).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.category)}</td><td class="mini">${esc(x.description||'')}</td><td class="num">${money(x.amount,x.currency)}</td><td>${x.status==='pending'?'<span class="badge b-warn">بانتظار</span>':x.status==='rejected'?'<span class="badge b-danger">مرفوض</span>':'<span class="badge b-ok">معتمد</span>'}</td></tr>`).join('')}</tbody></table>`:''}`:''}
    ${empTab==='att'?(()=>{const days=[];for(let i=29;i>=0;i--)days.push(iso(new Date(today().getTime()-i*86400000)));const as=days.map(d=>({d,a:attOf(e,d)}));const col={present:'#2FD1C0',field:'#12B5A6',mission:'#7C80F0',leave:'#F2A93C',sick:'#F2A93C',absent:'#E25555',off:'#4C6470'};const perf=notes.filter(n=>['إنجاز','شكر عميل','تقييم إيجابي','مخالفة','شكوى عميل','تأخير','إنذار','غياب بدون إذن'].includes(n.kind));return `<div class="kv" style="margin-bottom:14px"><div style="background:var(--accent-tint)"><small>درجة الأداء (90 يوم)</small><b style="font-size:1.3rem">${sc.score}</b>/100</div><div><small>إنجازات</small>${sc.good}</div><div><small>مخالفات</small>${sc.bad}</div><div><small>غياب</small>${sc.absent}</div><div><small>أيام ميدان</small>${sc.fieldDays}</div><div><small>اليوم</small>${(()=>{const a=attOf(e,iso(today()));return a?`<span class="badge ${ATT[a.status].cls}">${ATT[a.status].l}</span>${a.site?' '+esc(a.site):''}`:'<span class="badge b-muted">لم يُسجَّل</span>'})()}</div></div><h3>آخر 30 يوم</h3><div class="toolbar" style="gap:6px;margin-bottom:14px">${as.map(({d,a})=>`<span title="${fmtDate(d)}: ${a?ATT[a.status].l+(a.site?' — '+esc(a.site):''):'لم يُسجَّل'}" class="dot" style="width:16px;height:16px;margin:0;background:${a?col[a.status]:'rgba(255,255,255,.12)'}"></span>`).join('')}</div><div class="toolbar" style="margin-bottom:12px"><button class="btn" onclick="fieldDate=iso(today());openAttForm('${e.id}')">✏️ تسجيل حالة اليوم</button><button class="btn" onclick="fieldTab='perf';go('field')">＋ إنجاز / مخالفة</button></div>${perf.length?`<div class="timeline">${perf.map(n=>`<div><b class="mini muted">${fmtDate(n.date)}</b> <span class="badge ${['إنجاز','شكر عميل','تقييم إيجابي'].includes(n.kind)?'b-ok':'b-danger'}">${esc(n.kind)}</span> ${esc(n.text)}</div>`).join('')}</div>`:'<div class="empty">لا توجد إنجازات أو مخالفات مسجلة</div>'}`})():''}
    ${empTab==='leaves'?renderEmpLeaves(e,leaves,lb):''}
    ${empTab==='eos'?renderEOS(e):''}
    ${empTab==='letters'?renderLetterPicker(e):''}
    ${empTab==='account'?renderAccountTab(e):''}
    ${empTab==='assets'?renderAssetsTab(e):''}
    ${empTab==='prom'?renderPromTab(e):''}
    ${empTab==='timeline'?`<div class="toolbar" style="margin-bottom:14px"><select class="search" id="noteKind" style="min-width:130px"><option>ملاحظة</option><option>إنجاز</option><option>شكر عميل</option><option>ترقية</option><option>زيادة راتب</option><option>مخالفة</option><option>شكوى عميل</option><option>تأخير</option><option>إنذار</option></select><input class="search" id="noteText" placeholder="اكتب الملاحظة…" style="flex:1"><input type="date" class="search" id="noteDate" value="${iso(today())}" style="min-width:150px"><button class="btn primary" onclick="addNote('${e.id}')">إضافة</button></div>${notes.length?`<div class="timeline">${notes.map(n=>`<div><b class="mini muted">${fmtDate(n.date)}</b> <span class="badge ${['إنذار','مخالفة','شكوى عميل','تأخير','غياب بدون إذن'].includes(n.kind)?'b-danger':['ترقية','زيادة راتب','إنجاز','شكر عميل','تقييم إيجابي'].includes(n.kind)?'b-ok':'b-muted'}">${esc(n.kind||'ملاحظة')}</span> ${esc(n.text)} <button class="btn sm" style="float:left" onclick="delNote('${n.id}')">✕</button><button class="btn sm" style="float:left" onclick="editNote('${n.id}','${"$"}{empId}')">✏️</button></div>`).join('')}</div>`:'<div class="empty">لا توجد ملاحظات</div>'}`:''}
  </div>`;}
async function addNote(empId){const text=fv('noteText');if(!text)return;await DB.upsert('notes',{id:uid(),emp_id:empId,text,kind:fv('noteKind'),date:fv('noteDate')||iso(today())});render();}
async function editNote(id,empId){const n=S.notes.find(x=>x.id===id);if(!n)return;openModal('تعديل ملاحظة',`<div class="frow"><div class="field"><label>النوع</label><select id="en_kind">${['ملاحظة','إنجاز','شكر عميل','ترقية','زيادة راتب','مخالفة','شكوى عميل','تأخير','إنذار','تقييم إيجابي','غياب بدون إذن'].map(k=>`<option ${k===n.kind?'selected':''}>${k}</option>`).join('')}</select></div><div class="field"><label>التاريخ</label><input type="date" id="en_date" value="${esc(n.date||'')}"></div></div><div class="field"><label>النص</label><input id="en_text" value="${esc(n.text||'')}"></div>`,`<button class="btn primary" onclick="saveNoteEdit('${id}')">حفظ</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function saveNoteEdit(id){const n=S.notes.find(x=>x.id===id);if(!n)return;const text=fv('en_text');if(!text){toast('اكتب النص','err');return}await DB.upsert('notes',{...n,text,kind:fv('en_kind'),date:fv('en_date')||n.date});closeModal();toast('تم تعديل الملاحظة','ok');render();}
async function delNote(id){if(!await confirmDel('حذف هذه الملاحظة؟','حذف'))return;await DB.remove('notes',id);render();}
function renderEOS(e){window._eosAsOf=window._eosAsOf||{};const asOf=window._eosAsOf[e.id]||iso(today());const r=eosCalc(e,asOf);if(!r)return '<div class="empty">أدخل تاريخ التعيين أولاً</div>';const lb=leaveBalance(e);const leaveCash=(+e.basic||0)/30*Math.max(0,lb.balance);
  return `<div class="grid g2"><div><div class="field"><label>احتساب المكافأة حتى تاريخ</label><input type="date" value="${asOf}" onchange="window._eosAsOf['${e.id}']=this.value;render()"></div>
  <div class="kv"><div><small>مدة الخدمة</small><b>${r.years.toFixed(2)}</b> سنة (${r.svcDays} يوم)</div><div><small>أيام بدون راتب مستبعدة</small>${r.unpaid}</div><div><small>الأجر الأساسي</small>${money(r.basic,e.currency)}</div><div><small>الأجر اليومي (÷30)</small>${money(r.daily,e.currency)}</div>
  <div style="grid-column:1/-1;background:var(--primary-2)"><small>مكافأة نهاية الخدمة التقديرية</small><b style="font-size:1.4rem">${r.eligible?money(r.gratuity,e.currency):'غير مستحقة (أقل من سنة)'}</b>${r.eligible?`<div class="mini muted">≈ ${n0(toAED(r.gratuity,e.currency))} د.إ · الحد الأقصى أجر سنتين = ${money(r.cap,e.currency)}</div>`:''}</div>
  <div><small>بدل الإجازات غير المستخدمة (تقديري)</small>${money(leaveCash,e.currency)} <span class="mini muted">(${lb.balance} يوم × الأجر اليومي)</span></div><div><small>إجمالي المستحقات التقديرية</small><b>${money((r.eligible?r.gratuity:0)+leaveCash,e.currency)}</b></div></div></div>
  <div class="muted mini" style="line-height:1.8"><b>طريقة الحساب (المرسوم بقانون اتحادي 33 لسنة 2021 ولائحته):</b><br>• 21 يوم أجر أساسي عن كل سنة من السنوات الخمس الأولى.<br>• 30 يوم أجر أساسي عن كل سنة بعد الخامسة.<br>• تُحسب الأجزاء من السنة بالنسبة، ولا تُستحق قبل إتمام سنة خدمة متصلة.<br>• الأيام بدون راتب لا تدخل في مدة الخدمة، والإجمالي لا يتجاوز أجر سنتين.<br>• الأجر اليومي = الأساسي ÷ 30. البدلات لا تدخل في الحساب.<br><br>⚠️ هذا الرقم تقديري للاستئناس؛ راجع نص القانون أو مستشاراً قانونياً قبل التسوية النهائية، خاصة مع أنظمة التوفير البديلة أو المناطق الحرة.<br><br><button class="btn" onclick="openLetter('${e.id}','eos')">🧾 طباعة تسوية نهاية الخدمة</button></div></div>`;}

/* ==================== المستندات ==================== */
let docFilter={q:'',type:'',view:''};
function docRow(d,withEmp){const e=empById(d.emp_id);const st=docStatus(d);return `<tr>${withEmp?`<td><b data-go-emp="${d.emp_id}" style="cursor:pointer">${esc(e?e.name:'—')}</b></td>`:''}<td>${esc(d.type)}</td><td dir="ltr" style="text-align:right">${esc(d.number||'—')}</td><td>${fmtDate(d.issue_date)}</td><td><b>${fmtDate(d.expiry_date)}</b></td><td><span class="badge ${st.cls}">${st.txt}</span></td><td>${d.file_id?`<button class="btn sm" onclick="viewFile('${d.file_id}')">📎 عرض</button>`:'<span class="muted mini">—</span>'}</td><td><button class="btn sm" onclick="openDocForm('${d.emp_id}','${d.id}')">تعديل</button> <button class="btn sm" onclick="renewDoc('${d.id}')" title="تجديد">🔄</button></td></tr>`;}
let docTab='emp';
function renderDocuments(){const tabs=[['emp','👤 مستندات الموظفين'],['company','🏢 مستندات المنشأة'],['insurance','🏥 التأمين الصحي']];return `<div class="card tight" style="margin-bottom:16px"><div class="tabs" style="margin:0;padding:0 14px">${tabs.map(([k,l])=>`<button class="tab ${docTab===k?'active':''}" onclick="docTab='${k}';render()">${l}</button>`).join('')}</div></div>${docTab==='emp'?renderEmpDocs():docTab==='company'?renderCompanyDocs():renderInsurance()}`;}
function renderEmpDocs(){
  let list=S.documents.filter(d=>{if(d.emp_id==='company')return false;const e=empById(d.emp_id);if(!e||e.status==='inactive')return false;const st=docStatus(d);if(docFilter.view==='expired'&&st.lvl!==0)return false;if(docFilter.view==='soon'&&st.lvl!==1)return false;if(docFilter.view==='later'&&st.lvl!==2)return false;if(docFilter.view==='alerts'&&st.lvl>2)return false;if(docFilter.type&&d.type!==docFilter.type)return false;if(docFilter.q&&![e.name,d.type,d.number].join(' ').toLowerCase().includes(docFilter.q.toLowerCase()))return false;return true;});
  list.sort((a,b)=>{const x=docStatus(a),y=docStatus(b);return x.lvl-y.lvl||(x.days??1e9)-(y.days??1e9)});
  const missing=activeEmps().filter(e=>!S.documents.some(d=>d.emp_id===e.id&&d.type==='الإقامة'));
  return `${missing.length?`<div class="banner warn"><span>ℹ️ ${missing.length} موظف بدون مستند إقامة مسجّل: ${missing.slice(0,5).map(e=>esc(e.name)).join('، ')}${missing.length>5?'…':''}</span></div>`:''}
  <div class="card tight"><div class="card-head"><div class="toolbar">
    <input class="search" placeholder="🔍 بحث…" value="${esc(docFilter.q)}" oninput="docFilter.q=this.value;render()">
    <select class="search" style="min-width:150px" onchange="docFilter.type=this.value;render()"><option value="">كل الأنواع</option>${S.settings.docTypes.map(t=>`<option ${docFilter.type===t?'selected':''}>${esc(t)}</option>`).join('')}</select>
    <select class="search" style="min-width:160px" onchange="docFilter.view=this.value;render()"><option value="" ${!docFilter.view?'selected':''}>كل المستندات</option><option value="alerts" ${docFilter.view==='alerts'?'selected':''}>تحتاج متابعة</option><option value="expired" ${docFilter.view==='expired'?'selected':''}>منتهية</option><option value="soon" ${docFilter.view==='soon'?'selected':''}>تنتهي قريباً</option><option value="later" ${docFilter.view==='later'?'selected':''}>للمتابعة</option></select>
    </div><div class="toolbar"><span class="muted mini">${list.length} مستند</span><button class="btn" onclick="exportCSV('documents')">⬇️ تصدير Excel</button><button class="btn primary" onclick="openDocForm()">＋ مستند جديد</button></div></div>
    <div class="table-wrap">${list.length?`<table><thead><tr><th>الموظف</th><th>النوع</th><th>الرقم</th><th>الإصدار</th><th>الانتهاء</th><th>الحالة</th><th>الملف</th><th></th></tr></thead><tbody>${list.map(d=>docRow(d,true)).join('')}</tbody></table>`:'<div class="empty">لا توجد مستندات مطابقة</div>'}</div></div>`;}
function renderCompanyDocs(){const list=S.documents.filter(d=>d.emp_id==='company').sort((a,b)=>docStatus(a).lvl-docStatus(b).lvl||(docStatus(a).days??1e9)-(docStatus(b).days??1e9));const have=new Set(list.map(d=>d.type));const missing=S.settings.companyDocTypes.filter(t=>!have.has(t));
  return `<div class="card tight"><div class="card-head"><div><h2 style="margin:0">🏢 مستندات المنشأة (الرخصة، البطاقات، التأمينات، الشهادات)</h2><div class="muted mini">هذه هي أوراق "ملف التأهيل" التي تطلبها شركات المقاولات — سجّلها بتواريخها ليذكّرك البرنامج قبل انتهائها.</div></div><div class="toolbar"><button class="btn" onclick="openCompanyLetter('c_prequal')">📋 قائمة فحص التأهيل</button><button class="btn primary" onclick="openCompanyDocForm()">＋ مستند</button></div></div>
  <div class="table-wrap">${list.length?`<table><thead><tr><th>المستند</th><th>الرقم</th><th>الإصدار</th><th>الانتهاء</th><th>الحالة</th><th>الملف</th><th>ملاحظة</th><th></th></tr></thead><tbody>${list.map(d=>{const st=docStatus(d);return `<tr><td><b>${esc(d.type)}</b></td><td dir="ltr" style="text-align:right">${esc(d.number||'—')}</td><td>${fmtDate(d.issue_date)}</td><td><b>${fmtDate(d.expiry_date)}</b></td><td><span class="badge ${st.cls}">${st.txt}</span></td><td>${d.file_id?`<button class="btn sm" onclick="viewFile('${d.file_id}')">📎 عرض</button>`:'<span class="muted mini">—</span>'}</td><td class="mini">${esc(d.note||'')}</td><td><button class="btn sm" onclick="openCompanyDocForm('${d.id}')">تعديل</button> <button class="btn sm" onclick="renewDoc('${d.id}')">🔄</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">لم تُسجَّل مستندات للمنشأة بعد</div>'}</div></div>
  ${missing.length?`<div class="card"><h3>📌 مستندات لم تُسجَّل بعد</h3><div class="toolbar">${missing.map(t=>`<span class="chip cdoc-chip" data-type="${esc(t)}">＋ ${esc(t)}</span>`).join('')}</div></div>`:''}`;}
function openCompanyDocForm(docId,presetType){const d=docId?S.documents.find(x=>x.id===docId):{emp_id:'company',type:presetType||S.settings.companyDocTypes[0]};pendingFile=null;
  openModal(docId?'تعديل مستند المنشأة':'إضافة مستند للمنشأة',`<div class="frow"><div class="field"><label>نوع المستند *</label><input id="d_type" list="cdocList" value="${esc(d.type||'')}"><datalist id="cdocList">${S.settings.companyDocTypes.map(t=>`<option value="${esc(t)}">`).join('')}</datalist></div><div class="field"><label>الرقم</label><input id="d_num" value="${esc(d.number||'')}" dir="ltr"></div></div><div class="frow"><div class="field"><label>تاريخ الإصدار</label><input type="date" id="d_issue" value="${esc(d.issue_date||'')}"></div><div class="field"><label>تاريخ الانتهاء *</label><input type="date" id="d_exp" value="${esc(d.expiry_date||'')}"></div></div><div class="field"><label>صورة / ملف المستند</label><div class="toolbar"><button class="btn" onclick="pickDocFile()">📎 اختيار ملف</button><span id="d_fileName" class="muted mini">${d.file_name?esc(d.file_name)+' (محفوظ)':'لم يتم اختيار ملف'}</span></div></div><div class="field"><label>ملاحظة (الجهة المصدرة، الوسيط، رقم الملف…)</label><input id="d_note" value="${esc(d.note||'')}"></div><input type="hidden" id="d_emp" value="company">`,
  `<button class="btn primary" onclick="saveDoc('${docId||''}')">حفظ</button><button class="btn" onclick="closeModal()">إلغاء</button>${docId?`<button class="btn danger right" onclick="deleteDoc('${docId}')">🗑️ حذف</button>`:''}`);}
function renderInsurance(){const st=S.settings;const t=iso(today());const rows=activeEmps().map(e=>{const d=S.documents.filter(x=>x.emp_id===e.id&&x.type==='التأمين الطبي').sort((a,b)=>(b.expiry_date||'').localeCompare(a.expiry_date||''))[0];const du=d?daysUntil(d.expiry_date):null;return{e,d,du,state:!d?'missing':du<0?'expired':du<=30?'soon':'ok'}});const cnt=k=>rows.filter(r=>r.state===k).length;const pdu=st.policyEnd?daysUntil(st.policyEnd):null;
  return `<div class="grid g4" style="margin-bottom:16px"><div class="tile ${pdu!==null&&pdu<=30?'danger':'ok'}" onclick="setTab='company';go('settings')"><div class="lbl">🏥 البوليصة الجماعية</div><div class="num" style="font-size:1.1rem">${esc(st.insurer||'لم تُسجَّل')}</div><div class="sub">${st.policyNo?'رقم '+esc(st.policyNo)+' · ':''}${st.policyEnd?'تنتهي '+fmtDate(st.policyEnd)+(pdu!==null?' ('+pdu+' يوم)':''):'اضبط بياناتها من الإعدادات'}</div></div><div class="tile ok"><div class="lbl">مضافون بتأمين ساري</div><div class="num">${cnt('ok')}</div></div><div class="tile warn"><div class="lbl">تنتهي بطاقتهم خلال 30 يوم</div><div class="num">${cnt('soon')}</div></div><div class="tile ${cnt('missing')+cnt('expired')?'danger':'ok'}"><div class="lbl">مطلوب إضافتهم / تجديدهم</div><div class="num">${cnt('missing')+cnt('expired')}</div><div class="sub">لا يُسمح لهم بدخول مواقع العملاء</div></div></div>
  <div class="card tight"><div class="card-head"><h2>حالة التأمين الصحي لكل موظف</h2><div class="toolbar"><button class="btn" onclick="exportCSV('insurance')">⬇️ تصدير</button><button class="btn primary" onclick="LP={emps:${JSON.stringify(rows.filter(r=>r.state!=='ok').map(r=>r.e.id)).replace(/"/g,'&quot;')}};openCompanyLetter('c_insurance_census')">🖨️ كشف إضافة المطلوبين للتأمين</button></div></div><div class="table-wrap"><table><thead><tr><th>الموظف</th><th>المهنة</th><th>الحالة</th><th>رقم البطاقة</th><th>الانتهاء</th><th></th></tr></thead><tbody>${rows.sort((a,b)=>({missing:0,expired:1,soon:2,ok:3})[a.state]-({missing:0,expired:1,soon:2,ok:3})[b.state]).map(({e,d,du,state})=>`<tr><td><b data-go-emp="${e.id}" style="cursor:pointer">${esc(e.name)}</b><div class="muted mini">${esc(e.nationality||'')} · تعيين ${fmtDate(e.hire_date)}</div></td><td>${esc(e.trade||e.job||'')}</td><td>${state==='ok'?'<span class="badge b-ok">✅ مضاف وساري</span>':state==='soon'?`<span class="badge b-warn">⏳ ينتهي خلال ${du} يوم</span>`:state==='expired'?`<span class="badge b-danger">⛔ منتهٍ منذ ${-du} يوم</span>`:'<span class="badge b-danger">❗ غير مضاف — مطلوب إضافته</span>'}</td><td dir="ltr" style="text-align:right">${esc((d||{}).number||'—')}</td><td>${d?fmtDate(d.expiry_date):'—'}</td><td>${d?`<button class="btn sm" onclick="openDocForm('${e.id}','${d.id}')">تعديل</button> <button class="btn sm" onclick="renewDoc('${d.id}')">🔄</button>`:`<button class="btn sm primary" onclick="openDocForm('${e.id}');setTimeout(()=>{const s=document.getElementById('d_type');if(s)s.value='التأمين الطبي'},50)">＋ تسجيل الإضافة</button>`}</td></tr>`).join('')}</tbody></table></div></div>
  <div class="card"><h3>📌 المستندات المطلوبة لإضافة موظف للتأمين</h3><p class="muted mini">صورة الجواز · صورة الإقامة · الهوية الإماراتية · صورة شخصية · نموذج الإضافة (Census) · ربما فحص طبي حسب السن والفئة. بعد الإضافة سجّل رقم البطاقة وتاريخ انتهائها كمستند "التأمين الطبي" في ملف الموظف.</p></div>`;}
let pendingFile=null;
function openDocForm(empId,docId){if(!S.employees.length){toast('أضف موظفاً أولاً','err');return}const d=docId?S.documents.find(x=>x.id===docId):{emp_id:empId,type:S.settings.docTypes[0]};pendingFile=null;
  openModal(docId?'تعديل مستند':'إضافة مستند',`
  <div class="field"><label>الموظف *</label><select id="d_emp">${S.employees.filter(e=>e.status!=='inactive'||e.id===d.emp_id).map(e=>`<option value="${e.id}" ${e.id===d.emp_id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div>
  <div class="frow"><div class="field"><label>نوع المستند *</label>${selWithAdd('d_type','docTypes',d.type)}</div><div class="field"><label>رقم المستند</label><input id="d_num" value="${esc(d.number||'')}" dir="ltr"></div></div>
  <div class="frow"><div class="field"><label>تاريخ الإصدار</label><input type="date" id="d_issue" value="${esc(d.issue_date||'')}"></div><div class="field"><label>تاريخ الانتهاء *</label><input type="date" id="d_exp" value="${esc(d.expiry_date||'')}"></div></div>
  <div class="field"><label>صورة / ملف المستند (يُحفظ مشفّراً)</label><div class="toolbar"><button class="btn" onclick="pickDocFile()">📎 اختيار ملف</button><span id="d_fileName" class="muted mini">${d.file_name?esc(d.file_name)+' (محفوظ)':'لم يتم اختيار ملف'}</span>${d.file_id?`<button class="btn sm danger" onclick="removeDocFile('${d.id}')">إزالة الملف</button>`:''}</div></div>
  <div class="field"><label>ملاحظة</label><input id="d_note" value="${esc(d.note||'')}"></div>`,
  `<button class="btn primary" onclick="saveDoc('${docId||''}')">حفظ</button><button class="btn" onclick="closeModal()">إلغاء</button>${docId?`<button class="btn danger right" onclick="deleteDoc('${docId}')">🗑️ حذف</button>`:''}`);}
async function pickDocFile(){const f=await api.file.pick();if(!f)return;if(f.size>15*1024*1024){toast('حجم الملف كبير (الحد 15 ميجا)','err');return}pendingFile=f;$('#d_fileName').textContent=f.name+' ('+(f.size/1024).toFixed(0)+' ك.ب)';}
async function saveDoc(docId){const emp_id=fv('d_emp'),type=fv('d_type'),exp=fv('d_exp');if(emp_id==='company'&&type&&!S.settings.companyDocTypes.includes(type))await DB.setSetting('companyDocTypes',[...S.settings.companyDocTypes,type]);if(!emp_id||!type){toast('بيانات ناقصة','err');return}if(!exp){toast('تاريخ الانتهاء مطلوب','err');return}
  const d=docId?{...S.documents.find(x=>x.id===docId)}:{id:uid()};Object.assign(d,{emp_id,type,number:fv('d_num'),issue_date:fv('d_issue'),expiry_date:exp,note:fv('d_note')});
  const oldFile=d.file_id;if(pendingFile){d.file_id=uid();d.file_name=pendingFile.name;const bin=Uint8Array.from(atob(pendingFile.data),c=>c.charCodeAt(0));await api.file.save(d.file_id,pendingFile.name,pendingFile.mime,bin.buffer);}
  await DB.upsert('documents',d);if(pendingFile&&oldFile){await api.file.delete(oldFile);}pendingFile=null;closeModal();toast('تم حفظ المستند','ok');render();}
async function removeDocFile(docId){const d=S.documents.find(x=>x.id===docId);if(d&&d.file_id){await api.file.delete(d.file_id);await DB.upsert('documents',{...d,file_id:null,file_name:null});$('#d_fileName').textContent='لم يتم اختيار ملف';toast('تمت إزالة الملف');}}
async function deleteDoc(id){const d=S.documents.find(x=>x.id===id);closeModal();if(!await confirmDel(`حذف مستند "${d.type}"؟`))return;await DB.remove('documents',id);render();}
function renewDoc(id){const d=S.documents.find(x=>x.id===id);const base=d.expiry_date&&daysUntil(d.expiry_date)>0?parseD(d.expiry_date):today();
  openModal('تجديد '+esc(d.type),`<p class="muted">سيتم تحديث تاريخ الانتهاء وتسجيل التجديد في سجل الموظف.</p><div class="toolbar" style="margin-bottom:12px">${[1,2,3].map(y=>{const n=new Date(base);n.setFullYear(n.getFullYear()+y);return `<button class="btn" onclick="$('#r_exp').value='${iso(n)}'">+${y} سنة</button>`}).join('')}</div><div class="frow"><div class="field"><label>تاريخ الإصدار الجديد</label><input type="date" id="r_issue" value="${iso(today())}"></div><div class="field"><label>تاريخ الانتهاء الجديد</label><input type="date" id="r_exp" value=""></div></div><div class="field"><label>رقم المستند الجديد (اختياري)</label><input id="r_num" value="${esc(d.number||'')}" dir="ltr"></div>`,
  `<button class="btn primary" onclick="applyRenew('${id}')">تأكيد التجديد</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
async function applyRenew(id){const d=S.documents.find(x=>x.id===id);const exp=fv('r_exp');if(!exp){toast('أدخل تاريخ الانتهاء الجديد','err');return}await DB.upsert('notes',{id:uid(),emp_id:d.emp_id,date:iso(today()),kind:'ملاحظة',text:`تجديد ${d.type}: من ${fmtDate(d.expiry_date)} إلى ${fmtDate(exp)}`});await DB.upsert('documents',{...d,expiry_date:exp,issue_date:fv('r_issue'),number:fv('r_num')});closeModal();toast('تم تسجيل التجديد','ok');render();}
async function viewFile(fileId){const f=await api.file.get(fileId);if(!f){toast('الملف غير موجود','err');return}const bin=Uint8Array.from(atob(f.data),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bin],{type:f.mime}));const isImg=(f.mime||'').startsWith('image/');openModal(esc(f.name||'المستند'),`<div style="text-align:center">${isImg?`<img src="${url}" style="max-width:100%;max-height:65vh;border-radius:10px">`:`<iframe src="${url}" style="width:100%;height:65vh;border:0"></iframe>`}</div>`,`<a class="btn primary" href="${url}" download="${esc(f.name||'document')}">⬇️ حفظ نسخة</a><button class="btn" onclick="closeModal()">إغلاق</button>`,true);modalCleanup=()=>URL.revokeObjectURL(url);}
